// Status da turma. `em andamento` é derivado das datas (Turmas.situacao); `concluida` é gravado
// (semente: tudo que terminou até TURMA_SEED_HOJE) ou derivado quando o fim já passou.
const STATUS_TURMA = [
  { id: 'planejada', nome: 'Planejada', descricao: 'Datas previstas; ainda depende de vagas/confirmação.' },
  { id: 'confirmada', nome: 'Confirmada', descricao: 'Vai acontecer — instrutor, sala e datas fechados.' },
  { id: 'concluida', nome: 'Concluída', descricao: 'Aulas encerradas; histórico da turma.' },
  { id: 'cancelada', nome: 'Cancelada', descricao: 'Não vai acontecer; histórico preservado.' },
];

const TURMA_SEED_HOJE = '2026-08-26';
let _t = 0;
function turmaSeed(codigo, cursoId, inicio, fim, { edicao = null, tipo = 'formacao', agenda = null, instrutorId, salaId, alunos, vagas = null, status = null, meetLink = null, gravacoes = [], requisitos = null }) {
  _t += 1;
  const ag = edicao ? AGENDAS_EDICAO[edicao] : agenda;
  return {
    id: edicao ? `${edicao}-${cursoId}` : `ta${_t}`,
    codigo, cursoId, formacaoId: edicao, edicao, tipo,
    status: status ?? (fim <= TURMA_SEED_HOJE ? 'concluida' : inicio > TURMA_SEED_HOJE && tipo === 'aberta' ? 'planejada' : 'confirmada'),
    instrutorId, salaId,
    // Turma de formação herda a agenda da formação (`agenda: null`); avulsa guarda a própria.
    agenda: edicao ? null : ag,
    formato: ag.formato, turno: Agenda.descrever(ag),
    inicio, fim,
    vagas: vagas ?? Math.max(alunos ?? 0, { s1: 18, s2: 14, s3: 12, s4: 16, s5: 16, s13: 30 }[salaId] ?? 16),
    observacoes: '',
    // Google Meet: sala fixa da turma (instrutor e alunos online) e gravações registradas por aula (data).
    meetLink,
    gravacoes,
    // Requisitos de software/máquina da turma (docs/turmas.md RN10). `null` = ainda segue o curso;
    // turma nova nasce com a cópia do catálogo (Turmas.incluir).
    requisitos,
  };
}

// Gravação do Meet: { id, data (dia da aula), titulo, url, duracaoMin, observacoes }. Uma aula pode ter várias.
let _g = 0;
// Itens de requisito de uma turma: `reqCurso` veio do catálogo do curso na criação; `reqTurma` foi
// adicionado nesta turma (pela coordenação ou pelo instrutor, no Portal do Professor).
const reqCurso = (softwareId, nome, observacao = '') => ({ softwareId, nome, observacao, origem: 'curso', por: '' });
const reqTurma = (softwareId, nome, observacao, por) => ({ softwareId, nome, observacao, origem: 'turma', por });

const gravacaoSeed = (data, titulo, duracaoMin, observacoes = '') => ({ id: `g${++_g}`, data, titulo, url: `https://drive.google.com/file/d/1${data.replace(/-/g, '')}${_g}AbCdEfGhIjKlMnOp/view`, duracaoMin, observacoes });

